{"path": "solution.py", "content": "def validate_isbn10(s):
    """'0-306-40615-2' -> True."""
    # Remove dashes
    cleaned = s.replace('-', '')

    # Must be exactly 10 characters
    if len(cleaned) != 10:
        return False

    # First 9 must be digits
    for i in range(9):
        if not cleaned[i].isdigit():
            return False

    # Last character must be digit or 'X'
    last_char = cleaned[9]
    if last_char == 'X':
        last_digit = 10
    elif last_char.isdigit():
        last_digit = int(last_char)
    else:
        return False

    # Calculate weighted sum: (i+1) * digit for i=0..9
    total = 0
    for i in range(9):
        total += (i + 1) * int(cleaned[i])
    total += 10 * last_digit  # i=9, so weight is 10

    # Must be divisible by 11
    return total % 11 == 0"}

